#!/usr/bin/env python3
"""
Generates the satellite analysis HTML report.
"""
import csv, re, json
from collections import defaultdict

# ─── Load Data ────────────────────────────────────────────────────────────────
rows = []
with open('/app/benchmark/data.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append(row)

total = len(rows)

# ─── KPIs ─────────────────────────────────────────────────────────────────────
leo = [r for r in rows if float(r['MEAN_MOTION']) > 14]
leo_count, leo_pct = len(leo), round(len(leo)/total*100, 1)

geo = [r for r in rows if 0.9 <= float(r['MEAN_MOTION']) <= 1.1]
geo_count, geo_pct = len(geo), round(len(geo)/total*100, 1)

meo = [r for r in rows if 1.1 < float(r['MEAN_MOTION']) <= 14]
meo_count, meo_pct = len(meo), round(len(meo)/total*100, 1)

heo = [r for r in rows if float(r['MEAN_MOTION']) < 0.9]
heo_count, heo_pct = len(heo), round(len(heo)/total*100, 1)

starlink = [r for r in rows if r['OBJECT_NAME'].upper().startswith('STARLINK')]
starlink_count = len(starlink)

inclinations = sorted([float(r['INCLINATION']) for r in rows])
n = len(inclinations)
median_inc = (inclinations[n//2] + inclinations[(n-1)//2]) / 2

post2020 = sum(1 for r in rows
               if re.match(r'^(\d{4})-', r['OBJECT_ID'])
               and int(re.match(r'^(\d{4})-', r['OBJECT_ID']).group(1)) >= 2020)

# ─── Launch Years ─────────────────────────────────────────────────────────────
launch_years = defaultdict(int)
for r in rows:
    m = re.match(r'^(\d{4})-', r['OBJECT_ID'])
    if m:
        launch_years[int(m.group(1))] += 1

sorted_years = sorted(launch_years.items())

# ─── Operator Breakdown ───────────────────────────────────────────────────────
def classify_op(name):
    n = name.upper()
    if n.startswith('STARLINK'): return 'Starlink (SpaceX)'
    if n.startswith('ONEWEB') or n.startswith('ONE WEB'): return 'OneWeb'
    if n.startswith('IRIDIUM'): return 'Iridium'
    if n.startswith('GPS'): return 'GPS (USA)'
    if n.startswith('GLONASS'): return 'GLONASS (Russia)'
    if n.startswith('GALILEO'): return 'Galileo (EU)'
    if n.startswith('BEIDOU'): return 'BeiDou (China)'
    if n.startswith('O3B') or 'O3B MEO' in n: return 'O3b (SES)'
    if n.startswith('SES '): return 'SES'
    if n.startswith('INTELSAT'): return 'Intelsat'
    if n.startswith('EUTELSAT'): return 'Eutelsat'
    if n.startswith('VIASAT'): return 'Viasat'
    if n.startswith('HUGHES'): return 'Hughes'
    if n.startswith('CANOPUS'): return 'CANOPUS'
    if n.startswith('PLANET') or n.startswith('FLOCK'): return 'Planet (Flock/Skysat)'
    if n.startswith('SKYSAT'): return 'Planet (Skysat)'
    if n.startswith('RAPIDEYE'): return 'RapidEye'
    if n.startswith('AQUA') or n.startswith('TERRA'): return 'NASA Earth Science'
    if n.startswith('NOAA'): return 'NOAA Weather'
    if n.startswith('GOES'): return 'GOES Weather'
    if n.startswith('METEOR'): return 'Russian Weather'
    if n.startswith('COSMOS'): return 'Cosmos (Russia)'
    if n.startswith('YAML') or n.startswith('YAM'): return 'Yam (Astra)'
    if n.startswith('ORBCOMM'): return 'Orbcomm'
    if n.startswith('SWARM'): return 'Swarm (SpaceX)'
    if n.startswith('SPACEBEE'): return 'SpaceBee'
    if n.startswith('BLACKSKY') or n.startswith('BLACKSKY'): return 'BlackSky'
    if n.startswith('AST'): return 'AST SpaceMobile'
    if n.startswith('OMNI') or n.startswith('OMN'): return 'OmniWeb'
    if 'ISS' in n or n == 'ISS (ZARYA)': return 'ISS'
    if 'TIANGONG' in n: return 'Tiangong (China)'
    if n.startswith('LEO ') or n.startswith('LEO-') or n.startswith('GSE'): return 'SpaceX LEO'
    if n.startswith('LEMUR') or n.startswith('LEMUR'): return 'Lemur (Spaceflight)'
    if n.startswith('SHERPA') or n.startswith('SHERPA'): return 'Sherpa'
    if n.startswith('TRUCK') or n.startswith('TRUCK'): return 'Space Truck'
    return 'Other / Individual'

operators = defaultdict(int)
for r in rows:
    operators[classify_op(r['OBJECT_NAME'])] += 1

sorted_ops = sorted(operators.items(), key=lambda x: -x[1])
top_ops = sorted_ops[:15]

# ─── Inclination Breakdown ────────────────────────────────────────────────────
inc_buckets = defaultdict(int)
for r in rows:
    inc = float(r['INCLINATION'])
    bucket = int(inc // 10) * 10
    inc_buckets[bucket] += 1
inc_labels = sorted(inc_buckets.keys())
inc_values = [inc_buckets[k] for k in inc_labels]

# ─── Mean Motion Histogram ────────────────────────────────────────────────────
mm_hist = defaultdict(int)
for r in rows:
    mm = float(r['MEAN_MOTION'])
    bucket = round(mm, 1)
    mm_hist[bucket] += 1
mm_sorted = sorted(mm_hist.items())
mm_hist_labels = [str(k) for k, _ in mm_sorted]
mm_hist_values = [v for _, v in mm_sorted]

# ─── Eccentricity buckets ─────────────────────────────────────────────────────
ecc_buckets = {'< 0.01': 0, '0.01–0.05': 0, '0.05–0.10': 0, '0.10–0.30': 0, '0.30–0.60': 0, '>= 0.60': 0}
for r in rows:
    try:
        ecc = float('.' + r['ECCENTRICITY'].lstrip('.'))
        if ecc < 0.01: ecc_buckets['< 0.01'] += 1
        elif ecc < 0.05: ecc_buckets['0.01–0.05'] += 1
        elif ecc < 0.10: ecc_buckets['0.05–0.10'] += 1
        elif ecc < 0.30: ecc_buckets['0.10–0.30'] += 1
        elif ecc < 0.60: ecc_buckets['0.30–0.60'] += 1
        else: ecc_buckets['>= 0.60'] += 1
    except: pass
ecc_labels = list(ecc_buckets.keys())
ecc_values = list(ecc_buckets.values())

# ─── Starlink Inclination ─────────────────────────────────────────────────────
starlink_inc_buckets = defaultdict(int)
for r in starlink:
    inc = float(r['INCLINATION'])
    bucket = int(inc // 5) * 5
    starlink_inc_buckets[bucket] += 1
s_inc_labels = sorted(starlink_inc_buckets.keys())
s_inc_values = [starlink_inc_buckets[k] for k in s_inc_labels]

# ─── Build JSON data for charts ───────────────────────────────────────────────
launch_year_labels = [str(y) for y, _ in sorted_years]
launch_year_values = [v for _, v in sorted_years]

# ─── HTML ─────────────────────────────────────────────────────────────────────
html = """<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Active Satellites in Earth Orbit — 2026 Catalog Analysis</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --bg: #0d1117;
    --surface: #161b22;
    --surface2: #21262d;
    --border: #30363d;
    --text: #c9d1d9;
    --text-muted: #8b949e;
    --accent: #58a6ff;
    --accent2: #3fb950;
    --accent3: #f0883e;
    --accent4: #bc8cff;
    --starlink: #a371f7;
    --danger: #f85149;
    --kpi-bg: #161b22;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
    font-size: 14px;
  }
  a { color: var(--accent); text-decoration: none; }
  a:hover { text-decoration: underline; }

  /* ── HEADER ── */
  header {
    background: var(--surface);
    border-bottom: 1px solid var(--border);
    padding: 2rem 2rem 1.5rem;
    max-width: 1200px;
    margin: 0 auto;
  }
  .eyebrow {
    font-size: 11px;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-bottom: 0.5rem;
  }
  h1 {
    font-size: 1.75rem;
    font-weight: 700;
    color: #fff;
    margin-bottom: 0.25rem;
  }
  .subtitle {
    color: var(--text-muted);
    font-size: 13px;
    margin-top: 0.25rem;
  }

  /* ── MAIN ── */
  main {
    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem;
  }

  /* ── KPI STRIP ── */
  .kpi-strip {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 1px;
    background: var(--border);
    border: 1px solid var(--border);
    border-radius: 8px;
    overflow: hidden;
    margin-bottom: 2.5rem;
  }
  .kpi {
    background: var(--kpi-bg);
    padding: 1.25rem 1.5rem;
    text-align: center;
  }
  .kpi-value {
    font-size: 2rem;
    font-weight: 700;
    color: #fff;
    line-height: 1.1;
    font-variant-numeric: tabular-nums;
  }
  .kpi-label {
    font-size: 10px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-top: 0.35rem;
  }
  .kpi-sub {
    font-size: 11px;
    color: var(--text-muted);
    margin-top: 0.2rem;
  }
  .kpi-accent { color: var(--accent); }

  /* ── SECTION ── */
  .section {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
  }
  .section-header {
    padding: 1rem 1.5rem;
    border-bottom: 1px solid var(--border);
    display: flex;
    align-items: baseline;
    gap: 1rem;
  }
  .section-number {
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--text-muted);
    background: var(--surface2);
    border: 1px solid var(--border);
    border-radius: 4px;
    padding: 2px 8px;
  }
  h2 {
    font-size: 1rem;
    font-weight: 600;
    color: #fff;
  }
  .section-body { padding: 1.5rem; }

  /* ── CHARTS ── */
  .chart-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1.5rem;
    margin-top: 1rem;
  }
  .chart-grid-3 {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 1.5rem;
    margin-top: 1rem;
  }
  .chart-wrap { position: relative; }
  .chart-title {
    font-size: 11px;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-bottom: 0.75rem;
    font-weight: 600;
  }
  canvas { max-height: 280px; }
  .chart-full { margin-top: 1rem; }

  /* ── STAT TABLES ── */
  .stat-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.5rem 0;
    border-bottom: 1px solid var(--border);
    font-size: 13px;
  }
  .stat-row:last-child { border-bottom: none; }
  .stat-label { color: var(--text-muted); }
  .stat-value { font-weight: 600; color: #fff; font-variant-numeric: tabular-nums; }
  .stat-pct { color: var(--text-muted); font-size: 12px; margin-left: 0.5rem; }

  /* ── REGIME BAR ── */
  .regime-bar-container {
    margin: 1rem 0;
    display: flex;
    height: 48px;
    border-radius: 6px;
    overflow: hidden;
    border: 1px solid var(--border);
  }
  .regime-segment {
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    font-weight: 700;
    color: #fff;
    flex-direction: column;
    transition: flex-basis 0.3s;
    min-width: 40px;
  }
  .regime-segment .seg-label { font-size: 9px; font-weight: 400; opacity: 0.8; margin-top: 1px; }
  .regime-leo { background: #388bfd; }
  .regime-meo { background: #3fb950; }
  .regime-geo { background: #f0883e; }
  .regime-heo { background: #bc8cff; }

  /* ── CALLOUT ── */
  .callout {
    background: var(--surface2);
    border-left: 3px solid var(--accent);
    border-radius: 0 6px 6px 0;
    padding: 1rem 1.25rem;
    margin: 1rem 0;
    font-size: 13px;
    color: var(--text-muted);
  }
  .callout strong { color: var(--accent); }

  /* ── TWO COLUMN ── */
  .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 2rem; }

  /* ── FOOTER ── */
  footer {
    max-width: 1200px;
    margin: 0 auto 2rem;
    padding: 0 2rem;
    font-size: 11px;
    color: var(--text-muted);
    border-top: 1px solid var(--border);
    padding-top: 1rem;
  }

  /* ── BADGE ── */
  .badge {
    display: inline-block;
    padding: 2px 8px;
    border-radius: 20px;
    font-size: 11px;
    font-weight: 600;
  }
  .badge-starlink { background: rgba(163,113,247,0.2); color: var(--starlink); border: 1px solid rgba(163,113,247,0.4); }
  .badge-oneweb { background: rgba(63,185,80,0.15); color: var(--accent2); border: 1px solid rgba(63,185,80,0.3); }
  .badge-geo { background: rgba(240,136,62,0.15); color: var(--accent3); border: 1px solid rgba(240,136,62,0.3); }

  /* ── CONCLUSION LIST ── */
  .takeaway-list { list-style: none; }
  .takeaway-list li {
    display: flex;
    gap: 1rem;
    padding: 1rem 0;
    border-bottom: 1px solid var(--border);
    font-size: 13px;
  }
  .takeaway-list li:last-child { border-bottom: none; }
  .takeaway-num {
    font-size: 20px;
    font-weight: 700;
    color: var(--accent);
    line-height: 1;
    min-width: 32px;
  }
  .takeaway-text strong { color: #fff; display: block; margin-bottom: 0.2rem; }
  .takeaway-text { color: var(--text-muted); }

  @media (max-width: 900px) {
    .kpi-strip { grid-template-columns: repeat(3, 1fr); }
    .chart-grid, .chart-grid-3, .two-col { grid-template-columns: 1fr; }
  }
</style>
</head>
<body>

<header>
  <div class="eyebrow">CelesTrak / NORAD TLE Catalog · April 2026</div>
  <h1>Active Satellites in Earth Orbit</h1>
  <div class="subtitle">2026 Catalog Analysis · 14,875 active spacecraft · Space Industry & Policy Reference</div>
</header>

<main>

<!-- ═══════════════════════════════════════════════════════
     KPI STRIP
     ═══════════════════════════════════════════════════════ -->
<div class="kpi-strip">
  <div class="kpi">
    <div class="kpi-value">14,875</div>
    <div class="kpi-label">Total Active Satellites</div>
    <div class="kpi-sub kpi-accent">CelesTrak / NORAD TLE</div>
  </div>
  <div class="kpi">
    <div class="kpi-value">86.5%</div>
    <div class="kpi-label">LEO Share</div>
    <div class="kpi-sub">12,860 of 14,875</div>
  </div>
  <div class="kpi">
    <div class="kpi-value">10,083</div>
    <div class="kpi-label">Starlink Constellation</div>
    <div class="kpi-sub kpi-accent">67.8% of all active</div>
  </div>
  <div class="kpi">
    <div class="kpi-value">53.2°</div>
    <div class="kpi-label">Median Inclination</div>
    <div class="kpi-sub">All orbital regimes</div>
  </div>
  <div class="kpi">
    <div class="kpi-value">13,461</div>
    <div class="kpi-label">Launched Since 2020</div>
    <div class="kpi-sub kpi-accent">90.5% of active fleet</div>
  </div>
</div>


<!-- ═══════════════════════════════════════════════════════
     SECTION 1 — CATALOG OVERVIEW
     ═══════════════════════════════════════════════════════ -->
<div class="section">
  <div class="section-header">
    <span class="section-number">01</span>
    <h2>Catalog Overview &amp; Key Figures</h2>
  </div>
  <div class="section-body">
    <p style="color: var(--text-muted); font-size: 13px; margin-bottom: 1.5rem;">
      The CelesTrak / NORAD Two-Line Element (TLE) catalog captures <strong style="color:#fff">14,875 active satellites</strong>
      as of March–April 2026. The data reflects orbital elements updated continuously by the U.S. Space Force's
      18th Space Defense Squadron, with epoch dates concentrated in March 2026 — confirming data freshness.
      The catalog excludes debris and non-operational objects.
    </p>
