#!/usr/bin/env python3
"""
Generates the satellite analysis HTML report.
"""
import csv, re, json
from collections import defaultdict

# ─── Load Data ────────────────────────────────────────────────────────────────
rows = []
with open('/app/benchmark/data.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append(row)

total = len(rows)

# ─── KPIs ─────────────────────────────────────────────────────────────────────
leo = [r for r in rows if float(r['MEAN_MOTION']) > 14]
leo_count, leo_pct = len(leo), round(len(leo)/total*100, 1)

geo = [r for r in rows if 0.9 <= float(r['MEAN_MOTION']) <= 1.1]
geo_count, geo_pct = len(geo), round(len(geo)/total*100, 1)

meo = [r for r in rows if 1.1 < float(r['MEAN_MOTION']) <= 14]
meo_count, meo_pct = len(meo), round(len(meo)/total*100, 1)

heo = [r for r in rows if float(r['MEAN_MOTION']) < 0.9]
heo_count, heo_pct = len(heo), round(len(heo)/total*100, 1)

starlink = [r for r in rows if r['OBJECT_NAME'].upper().startswith('STARLINK')]
starlink_count = len(starlink)

inclinations = sorted([float(r['INCLINATION']) for r in rows])
n = len(inclinations)
median_inc = (inclinations[n//2] + inclinations[(n-1)//2]) / 2

post2020 = sum(1 for r in rows
               if re.match(r'^(\d{4})-', r['OBJECT_ID'])
               and int(re.match(r'^(\d{4})-', r['OBJECT_ID']).group(1)) >= 2020)

# ─── Launch Years ─────────────────────────────────────────────────────────────
launch_years = defaultdict(int)
for r in rows:
    m = re.match(r'^(\d{4})-', r['OBJECT_ID'])
    if m:
        launch_years[int(m.group(1))] += 1

sorted_years = sorted(launch_years.items())

# ─── Operator Breakdown ───────────────────────────────────────────────────────
def classify_op(name):
    n = name.upper()
    if n.startswith('STARLINK'): return 'Starlink (SpaceX)'
    if n.startswith('ONEWEB') or n.startswith('ONE WEB'): return 'OneWeb'
    if n.startswith('IRIDIUM'): return 'Iridium'
    if n.startswith('GPS'): return 'GPS (USA)'
    if n.startswith('GLONASS'): return 'GLONASS (Russia)'
    if n.startswith('GALILEO'): return 'Galileo (EU)'
    if n.startswith('BEIDOU'): return 'BeiDou (China)'
    if n.startswith('O3B') or 'O3B MEO' in n: return 'O3b (SES)'
    if n.startswith('SES '): return 'SES'
    if n.startswith('INTELSAT'): return 'Intelsat'
    if n.startswith('EUTELSAT'): return 'Eutelsat'
    if n.startswith('VIASAT'): return 'Viasat'
    if n.startswith('HUGHES'): return 'Hughes'
    if n.startswith('CANOPUS'): return 'CANOPUS'
    if n.startswith('PLANET') or n.startswith('FLOCK'): return 'Planet (Flock/Skysat)'
    if n.startswith('SKYSAT'): return 'Planet (Skysat)'
    if n.startswith('RAPIDEYE'): return 'RapidEye'
    if n.startswith('AQUA') or n.startswith('TERRA'): return 'NASA Earth Science'
    if n.startswith('NOAA'): return 'NOAA Weather'
    if n.startswith('GOES'): return 'GOES Weather'
    if n.startswith('METEOR'): return 'Russian Weather'
    if n.startswith('COSMOS'): return 'Cosmos (Russia)'
    if n.startswith('YAML') or n.startswith('YAM'): return 'Yam (Astra)'
    if n.startswith('ORBCOMM'): return 'Orbcomm'
    if n.startswith('SWARM'): return 'Swarm (SpaceX)'
    if n.startswith('SPACEBEE'): return 'SpaceBee'
    if n.startswith('BLACKSKY') or n.startswith('BLACKSKY'): return 'BlackSky'
    if n.startswith('AST'): return 'AST SpaceMobile'
    if n.startswith('OMNI') or n.startswith('OMN'): return 'OmniWeb'
    if 'ISS' in n or n == 'ISS (ZARYA)': return 'ISS'
    if 'TIANGONG' in n: return 'Tiangong (China)'
    if n.startswith('LEO ') or n.startswith('LEO-') or n.startswith('GSE'): return 'SpaceX LEO'
    if n.startswith('LEMUR') or n.startswith('LEMUR'): return 'Lemur (Spaceflight)'
    if n.startswith('SHERPA') or n.startswith('SHERPA'): return 'Sherpa'
    if n.startswith('TRUCK') or n.startswith('TRUCK'): return 'Space Truck'
    return 'Other / Individual'

operators = defaultdict(int)
for r in rows:
    operators[classify_op(r['OBJECT_NAME'])] += 1

sorted_ops = sorted(operators.items(), key=lambda x: -x[1])
top_ops = sorted_ops[:15]

# ─── Inclination Breakdown ────────────────────────────────────────────────────
inc_buckets = defaultdict(int)
for r in rows:
    inc = float(r['INCLINATION'])
    bucket = int(inc // 10) * 10
    inc_buckets[bucket] += 1
inc_labels = sorted(inc_buckets.keys())
inc_values = [inc_buckets[k] for k in inc_labels]

# ─── Mean Motion Histogram ────────────────────────────────────────────────────
mm_hist = defaultdict(int)
for r in rows:
    mm = float(r['MEAN_MOTION'])
    bucket = round(mm, 1)
    mm_hist[bucket] += 1
mm_sorted = sorted(mm_hist.items())
mm_hist_labels = [str(k) for k, _ in mm_sorted]
mm_hist_values = [v for _, v in mm_sorted]

# ─── Eccentricity buckets ─────────────────────────────────────────────────────
ecc_buckets = {'< 0.01': 0, '0.01–0.05': 0, '0.05–0.10': 0, '0.10–0.30': 0, '0.30–0.60': 0, '>= 0.60': 0}
for r in rows:
    try:
        ecc = float('.' + r['ECCENTRICITY'].lstrip('.'))
        if ecc < 0.01: ecc_buckets['< 0.01'] += 1
        elif ecc < 0.05: ecc_buckets['0.01–0.05'] += 1
        elif ecc < 0.10: ecc_buckets['0.05–0.10'] += 1
        elif ecc < 0.30: ecc_buckets['0.10–0.30'] += 1
        elif ecc < 0.60: ecc_buckets['0.30–0.60'] += 1
        else: ecc_buckets['>= 0.60'] += 1
    except: pass
ecc_labels = list(ecc_buckets.keys())
ecc_values = list(ecc_buckets.values())

# ─── Starlink Inclination ─────────────────────────────────────────────────────
starlink_inc_buckets = defaultdict(int)
for r in starlink:
    inc = float(r['INCLINATION'])
    bucket = int(inc // 5) * 5
    starlink_inc_buckets[bucket] += 1
s_inc_labels = sorted(starlink_inc_buckets.keys())
s_inc_values = [starlink_inc_buckets[k] for k in s_inc_labels]

# ─── Build JSON data for charts ───────────────────────────────────────────────
launch_year_labels = [str(y) for y, _ in sorted_years]
launch_year_values = [v for _, v in sorted_years]

# ─── HTML ─────────────────────────────────────────────────────────────────────
html = """<!DOCTYPE html>
