<div class="stat-row"><span class="stat-label">GEO &nbsp; 0.9 &le; Mean Motion &le; 1.1</span><span class="stat-value">596 <span class="stat-pct">(4.0%)</span></span></div>
<div class="stat-row"><span class="stat-label">HEO &nbsp; Mean Motion &lt; 0.9</span><span class="stat-value">11 <span class="stat-pct">(0.1%)</span></span></div>
