#!/usr/bin/env python3
"""Generates the satellite analysis HTML report."""
import csv, re, json as jsonmod
from collections import defaultdict

# ─── Load Data ────────────────────────────────────────────────────────────────
rows = []
with open('/app/benchmark/data.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append(row)

total = len(rows)

leo    = [r for r in rows if float(r['MEAN_MOTION']) > 14]
geo    = [r for r in rows if 0.9 <= float(r['MEAN_MOTION']) <= 1.1]
meo    = [r for r in rows if 1.1 < float(r['MEAN_MOTION']) <= 14]
heo    = [r for r in rows if float(r['MEAN_MOTION']) < 0.9]
starlink = [r for r in rows if r['OBJECT_NAME'].upper().startswith('STARLINK')]
starlink_count = len(starlink)

inclinations = sorted([float(r['INCLINATION']) for r in rows])
n = len(inclinations)
median_inc = (inclinations[n//2] + inclinations[(n-1)//2]) / 2

post2020 = sum(
    1 for r in rows
    if re.match(r'^(\d{4})-', r['OBJECT_ID'])
    and int(re.match(r'^(\d{4})-', r['OBJECT_ID']).group(1)) >= 2020
)

launch_years = defaultdict(int)
for r in rows:
    m = re.match(r'^(\d{4})-', r['OBJECT_ID'])
    if m:
        launch_years[int(m.group(1))] += 1

sorted_years = sorted(launch_years.items())

cum_vals = []
running = 0
for _, v in sorted_years:
    running += v
    cum_vals.append(running)

def classify_op(name):
    n2 = name.upper()
    if n2.startswith('STARLINK'): return 'Starlink (SpaceX)'
    if n2.startswith('ONEWEB') or n2.startswith('ONE WEB'): return 'OneWeb'
    if n2.startswith('IRIDIUM'): return 'Iridium'
    if n2.startswith('GPS'): return 'GPS (USA)'
    if n2.startswith('GLONASS'): return 'GLONASS (Russia)'
    if n2.startswith('GALILEO'): return 'Galileo (EU)'
    if n2.startswith('BEIDOU'): return 'BeiDou (China)'
    if n2.startswith('O3B') or 'O3B MEO' in n2: return 'O3b (SES)'
    if n2.startswith('SES '): return 'SES'
    if n2.startswith('INTELSAT'): return 'Intelsat'
    if n2.startswith('EUTELSAT'): return 'Eutelsat'
    if n2.startswith('VIASAT'): return 'Viasat'
    if n2.startswith('HUGHES'): return 'Hughes'
    if n2.startswith('CANOPUS'): return 'CANOPUS'
    if n2.startswith('PLANET') or n2.startswith('FLOCK'): return 'Planet (Flock/Skysat)'
    if n2.startswith('SKYSAT'): return 'Planet (Skysat)'
    if n2.startswith('RAPIDEYE'): return 'RapidEye'
    if n2.startswith('AQUA') or n2.startswith('TERRA'): return 'NASA Earth Science'
    if n2.startswith('NOAA'): return 'NOAA Weather'
    if n2.startswith('GOES'): return 'GOES Weather'
    if n2.startswith('METEOR'): return 'Russian Weather'
    if n2.startswith('COSMOS'): return 'Cosmos (Russia)'
    if n2.startswith('YAML') or n2.startswith('YAM'): return 'Yam (Astra)'
    if n2.startswith('ORBCOMM'): return 'Orbcomm'
    if n2.startswith('SWARM'): return 'Swarm (SpaceX)'
    if n2.startswith('SPACEBEE'): return 'SpaceBee'
    if n2.startswith('BLACKSKY') or n2.startswith('BLACKSKY'): return 'BlackSky'
    if n2.startswith('AST'): return 'AST SpaceMobile'
    if n2.startswith('OMNI') or n2.startswith('OMN'): return 'OmniWeb'
    if 'ISS' in n2 or n2 == 'ISS (ZARYA)': return 'ISS'
    if 'TIANGONG' in n2: return 'Tiangong (China)'
    if n2.startswith('LEO ') or n2.startswith('LEO-') or n2.startswith('GSE'): return 'SpaceX LEO'
    if n2.startswith('LEMUR') or n2.startswith('LEMUR'): return 'Lemur (Spaceflight)'
    if n2.startswith('SHERPA') or n2.startswith('SHERPA'): return 'Sherpa'
    if n2.startswith('TRUCK') or n2.startswith('TRUCK'): return 'Space Truck'
    return 'Other / Individual'

operators = defaultdict(int)
for r in rows:
    operators[classify_op(r['OBJECT_NAME'])] += 1

sorted_ops = sorted(operators.items(), key=lambda x: -x[1])
top_ops = sorted_ops[:15]

inc_buckets = defaultdict(int)
for r in rows:
    inc = float(r['INCLINATION'])
    bucket = int(inc // 10) * 10
    inc_buckets[bucket] += 1
inc_labels = sorted(inc_buckets.keys())
inc_values = [inc_buckets[k] for k in inc_labels]

mm_hist = defaultdict(int)
for r in rows:
    mm = float(r['MEAN_MOTION'])
    bucket = round(mm, 1)
    mm_hist[bucket] += 1
mm_sorted = sorted(mm_hist.items())
mm_hist_labels = [str(k) for k, _ in mm_sorted]
mm_hist_values = [v for _, v in mm_sorted]

ecc_buckets = {'< 0.01': 0, '0.01-0.05': 0, '0.05-0.10': 0, '0.10-0.30': 0, '0.30-0.60': 0, '>= 0.60': 0}
for r in rows:
    try:
        ecc = float('.' + r['ECCENTRICITY'].lstrip('.'))
        if ecc < 0.01: ecc_buckets['< 0.01'] += 1
        elif ecc < 0.05: ecc_buckets['0.01-0.05'] += 1
        elif ecc < 0.10: ecc_buckets['0.05-0.10'] += 1
        elif ecc < 0.30: ecc_buckets['0.10-0.30'] += 1
        elif ecc < 0.60: ecc_buckets['0.30-0.60'] += 1
        else: ecc_buckets['>= 0.60'] += 1
    except: pass
ecc_labels = list(ecc_buckets.keys())
ecc_values = list(ecc_buckets.values())

starlink_inc_buckets = defaultdict(int)
for r in starlink:
    inc = float(r['INCLINATION'])
    bucket = int(inc // 5) * 5
    starlink_inc_buckets[bucket] += 1
s_inc_labels = sorted(starlink_inc_buckets.keys())
s_inc_values = [starlink_inc_buckets[k] for k in s_inc_labels]

excl_starlink_ops = sorted_ops[1:12]

recent_years_data = [(y, v) for y, v in sorted_years if y >= 2015]

# ─── Serialize chart data ──────────────────────────────────────────────────────
def j(val): return jsonmod.dumps(val)

mm_labels_js   = j(mm_hist_labels)
mm_values_js   = j(mm_hist_values)
inc_labels_js  = j([str(k)+'\u00b0' for k in inc_labels])
inc_values_js  = j(inc_values)
ecc_labels_js  = j(ecc_labels)
ecc_values_js  = j(ecc_values)
op_names_js    = j([op for op, _ in top_ops])
op_counts_js   = j([cnt for _, cnt in top_ops])
op_colors_js   = j(['#a371f7' if op == 'Starlink (SpaceX)' else '#3fb950' if cnt > 500 else '#58a6ff' for op, cnt in top_ops])
sl_inc_lbl_js  = j([str(k)+'\u00b0' for k in s_inc_labels])
sl_inc_val_js  = j(s_inc_values)
excl_sl_n_js   = j([op for op, _ in excl_starlink_ops])
excl_sl_c_js   = j([cnt for _, cnt in excl_starlink_ops])
ly_lbl_js      = j([str(y) for y, _ in sorted_years])
ly_val_js      = j([v for _, v in sorted_years])
recent_lbl_js  = j([str(y) for y, _ in recent_years_data])
recent_val_js  = j([v for _, v in recent_years_data])
cum_lbl_js     = j([str(y) for y, _ in sorted_years])
cum_val_js     = j(cum_vals)

# ─── Chart initialization script (all JS, no template) ────────────────────────
SCRIPTS = """
<script>
Chart.defaults.color = '#8b949e';
Chart.defaults.borderColor = '#30363d';
Chart.defaults.font.family = "-apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif";
Chart.defaults.font.size = 11;

new Chart(document.getElementById('chart-mm'), {
  type: 'bar',
  data: {
    labels: """ + mm_labels_js + """,
    datasets: [{
      label: 'Satellites',
      data: """ + mm_values_js + """,
      backgroundColor: 'rgba(88,166,255,0.5)',
      borderColor: 'rgba(88,166,255,0.8)',
      borderWidth: 1,
    }]
  },
  options: {
    plugins: { legend: { display: false } },
    scales: {
      x: { title: { display: true, text: 'Mean Motion (rev/day)', color: '#8b949e' }, ticks: { maxTicksLimit: 16 } },
      y: { title: { display: true, text: 'Count', color: '#8b949e' } }
    }
  }
});

new Chart(document.getElementById('chart-inc'), {
  type: 'bar',
  data: {
    labels: """ + inc_labels_js + """,
    datasets: [{
      label: 'Satellites',
      data: """ + inc_values_js + """,
      backgroundColor: 'rgba(63,185,80,0.5)',
      borderColor: 'rgba(63,185,80,0.8)',
      borderWidth: 1,
    }]
  },
  options: {
    plugins: { legend: { display: false } },
    scales: {
      x: { title: { display: true, text: 'Inclination (deg)', color: '#8b949e' } },
      y: { title: { display: true, text: 'Count', color: '#8b949e' } }
    }
  }
});

new Chart(document.getElementById('chart-ecc'), {
  type: 'doughnut',
  data: {
    labels: """ + ecc_labels_js + """,
    datasets: [{
      data: """ + ecc_values_js + """,
      backgroundColor: ['rgba(88,166,255,0.7)','rgba(63,185,80,0.7)','rgba(240,136,62,0.7)','rgba(188,140,255,0.7)','rgba(248,81,73,0.7)','rgba(210,168,255,0.7)'],
      borderColor: '#0d1117',
      borderWidth: 2,
    }]
  },
  options: {
    plugins: { legend: { position: 'right', labels: { padding: 12, boxWidth: 12 } } }
  }
});

new Chart(document.getElementById('chart-regime-pie'), {
  type: 'doughnut',
  data: {
    labels: ['LEO (MM>14)','MEO (1.1<MM\u226414)','GEO (0.9\u2264MM\u22641.1)','HEO (MM<0.9)'],
    datasets: [{
      data: [12860, 1408, 596, 11],
      backgroundColor: ['#388bfd','#3fb950','#f0883e','#bc8cff'],
      borderColor: '#0d1117',
      borderWidth: 2,
    }]
  },
  options: {
    plugins: { legend: { position: 'bottom', labels: { padding: 10, boxWidth: 12 } } }
  }
});

new Chart(document.getElementById('chart-operators'), {
  type: 'bar',
  data: {
    labels: """ + op_names_js + """,
    datasets: [{
      label: 'Satellites',
      data: """ + op_counts_js + """,
      backgroundColor: """ + op_colors_js + """,
      borderRadius: 4,
    }]
  },
  options: {
    indexAxis: 'y',
    plugins: { legend: { display: false } },
    scales: {
      x: { title: { display: true, text: 'Count', color: '#8b949e' } }
    }
  }
});

new Chart(document.getElementById('chart-starlink-inc'), {
  type: 'bar',
  data: {
    labels: """ + sl_inc_lbl_js + """,
    datasets: [{
      label: 'Starlink sats',
      data: """ + sl_inc_val_js + """,
      backgroundColor: 'rgba(163,113,247,0.6)',
      borderColor: 'rgba(163,113,247,0.9)',
      borderWidth: 1,
      borderRadius: 4,
    }]
  },
  options: {
    plugins: { legend: { display: false } },
    scales: {
      x: { title: { display: true, text: 'Inclination band', color: '#8b949e' } },
      y: { title: { display: true, text: 'Count', color: '#8b949e' } }
    }
  }
});

new Chart(document.getElementById('chart-ops-excl-starlink'), {
  type: 'doughnut',
  data: {
    labels: """ + excl_sl_n_js + """,
    datasets: [{
      data: """ + excl_sl_c_js + """,
      backgroundColor: ['rgba(63,185,80,0.7)','rgba(163,113,247,0.7)','rgba(88,166,255,0.7)','rgba(240,136,62,0.7)','rgba(248,81,73,0.7)','rgba(188,140,255,0.7)','rgba(210,153,34,0.7)','rgba(56,139,253,0.7)','rgba(63,185,80,0.5)','rgba(255,123,114,0.7)','rgba(121,192,255,0.7)'],
      borderColor: '#0d1117',
      borderWidth: 2,
    }]
  },
  options: {
    plugins: { legend: { position: 'right', labels: { padding: 8, boxWidth: 10, font: { size: 10 } } } }
  }
});

new Chart(document.getElementById('chart-launch-full'), {
  type: 'bar',
  data: {
    labels: """ + ly_lbl_js + """,
    datasets: [{
      label: 'Active satellites',
      data: """ + ly_val_js + """,
      backgroundColor: function(ctx) {
        const year = parseInt(ctx.chart.data.labels[ctx.dataIndex]);
        if (year >= 2020) return 'rgba(88,166,255,0.75)';
        if (year >= 2015) return 'rgba(63,185,80,0.6)';
        return 'rgba(139,148,158,0.4)';
      },
      borderRadius: 2,
      borderSkipped: false,
    }]
  },
  options: {
    plugins: { legend: { display: false } },
    scales: {
      x: { title: { display: true, text: 'Launch Year', color: '#8b949e' }, ticks: { maxTicksLimit: 20 } },
      y: { title: { display: true, text: 'Active Satellites', color: '#8b949e' } }
    }
  }
});

new Chart(document.getElementById('chart-launch-recent'), {
  type: 'bar',
  data: {
    labels: """ + recent_lbl_js + """,
    datasets: [{
      label: 'Active satellites',
      data: """ + recent_val_js + """,
